// ═══════════════════════════════════════════════════════════════════════════════
// GRAIN TERMINAL SIMULATOR v2.0 - REALÍSTICO
// Terminal de Grãos 2000 t/h - Exportação Marítima
// ═══════════════════════════════════════════════════════════════════════════════
//
// FLUXO DO PROCESSO:
// Armazém → Vazadores (ARZ) → Correia 01 → Correia 02 → Elevador → 
// Balança de Fluxo → Correia 03 → Tripper/Shiploader
//
// EQUIPAMENTOS:
// - MOE01: Moega de Recebimento (caminhões)
// - ARZ_GATES: 4 Vazadores de Armazém (não 7, mais realista)
// - CORR01: Correia Coletora (600 t/h) - coleta dos vazadores
// - CORR02: Correia Transportadora (1200 t/h) - transporte horizontal  
// - ELV01: Elevador de Canecas (1500 t/h) - elevação vertical
// - BLC01: Balança de Fluxo (2000 t/h) - pesagem contínua - CRÍTICO!
// - CORR03: Correia de Embarque (2000 t/h) - alimenta shiploader
// - TRP01: Tripper Car - distribui entre porões
// - SLD01: Shiploader (2000 t/h) - carrega navio
// ═══════════════════════════════════════════════════════════════════════════════

const timestamp = new Date().toISOString();

let state = context.get('state') || {
    running: true,
    time_s: 0,
    start_time: Date.now(),
    operation_mode: 'LOADING', // LOADING, RECEIVING, IDLE

    // ═══ MOEGA DE RECEBIMENTO (MOE01) ═══
    // Recebe caminhões - geralmente 30-40 t por caminhão
    hopper: {
        level_pct: 35,        // Nível da moega (%)
        flow_tph: 0,          // Vazão de descarga (t/h)
        truck_count: 0,       // Contador de caminhões
        weight_t: 0,          // Peso atual (t)
        capacity_t: 100,      // Capacidade máxima (t)
        gate_open: false,     // Comporta aberta
        vibrator_on: false    // Vibrador ativo
    },

    // ═══ VAZADORES DE ARMAZÉM (4 unidades) ═══
    // Cada vazador: máx 300 t/h, abertura 0-100%
    gates: [
        { id: 1, setpoint: 75, opening: 0, flow: 0, max_flow: 300, tau: 2.5, fault: false },
        { id: 2, setpoint: 80, opening: 0, flow: 0, max_flow: 300, tau: 2.5, fault: false },
        { id: 3, setpoint: 70, opening: 0, flow: 0, max_flow: 300, tau: 2.5, fault: false },
        { id: 4, setpoint: 85, opening: 0, flow: 0, max_flow: 300, tau: 2.5, fault: false }
    ],

    // ═══ CORREIAS TRANSPORTADORAS ═══
    belts: {
        CORR01: {
            name: 'Correia Coletora',
            running: true,
            speed_mps: 0,         // Velocidade real (m/s)
            speed_sp: 2.5,        // Setpoint velocidade
            flow_tph: 0,          // Vazão atual
            capacity_tph: 600,    // Capacidade nominal
            load_pct: 0,          // Carga (%)
            power_kw: 0,          // Potência consumida
            current_a: 0,         // Corrente motor
            motor_temp_c: 35,     // Temp motor
            bearing_temp_c: 40,   // Temp mancal
            vibration_mms: 1.2,   // Vibração
            belt_slip: false,     // Patinamento
            pull_cord: false      // Cordinha puxada
        },
        CORR02: {
            name: 'Correia Transportadora',
            running: true,
            speed_mps: 0,
            speed_sp: 3.0,
            flow_tph: 0,
            capacity_tph: 1200,
            load_pct: 0,
            power_kw: 0,
            current_a: 0,
            motor_temp_c: 35,
            bearing_temp_c: 40,
            vibration_mms: 1.0,
            belt_slip: false,
            pull_cord: false
        },
        CORR03: {
            name: 'Correia de Embarque',
            running: true,
            speed_mps: 0,
            speed_sp: 3.5,
            flow_tph: 0,
            capacity_tph: 2000,
            load_pct: 0,
            power_kw: 0,
            current_a: 0,
            motor_temp_c: 35,
            bearing_temp_c: 40,
            vibration_mms: 0.8,
            belt_slip: false,
            pull_cord: false
        }
    },

    // ═══ ELEVADOR DE CANECAS (ELV01) ═══
    elevator: {
        running: true,
        speed_mps: 0,
        speed_sp: 2.8,
        flow_tph: 0,
        capacity_tph: 1500,
        power_kw: 0,
        current_a: 0,
        motor_temp_c: 45,
        bearing_temp_c: 50,
        vibration_mms: 1.5,
        bucket_count: 0,
        head_pressure: 0,     // Pressão na cabeça
        boot_level_pct: 30,   // Nível no pé
        belt_alignment: true  // Alinhamento correia
    },

    // ═══ BALANÇA DE FLUXO (BLC01) - EQUIPAMENTO CRÍTICO! ═══
    scale: {
        flow_tph: 0,              // Vazão instantânea
        flow_sp: 1800,            // Setpoint vazão
        total_t: 0,               // Totalização (t)
        daily_total_t: 0,         // Total diário
        speed_mps: 3.2,           // Velocidade da correia
        belt_load_kg_m: 0,        // Carga linear (kg/m)
        calibration_ok: true,     // Calibração OK
        zero_ok: true,            // Zero OK
        last_cal_date: '2024-01-15',
        accuracy_pct: 0.25,       // Precisão 0.25%
        integration_time_s: 10    // Tempo integração
    },

    // ═══ TRIPPER CAR (TRP01) ═══
    tripper: {
        position_m: 50,       // Posição (0-200m)
        speed_mpm: 0,         // Velocidade (m/min)
        target_position: 50,  // Posição alvo
        bay_selected: 3,      // Porão selecionado (1-5)
        travel_fault: false,
        limit_left: false,
        limit_right: false
    },

    // ═══ SHIPLOADER (SLD01) ═══
    shiploader: {
        flow_tph: 0,
        flow_sp: 1800,
        power_kw: 0,
        current_a: 0,
        boom_angle_deg: 12,    // Ângulo lança (0-45°)
        boom_length_m: 35,     // Comprimento lança
        slewing_deg: 0,        // Giro (-180 a +180)
        shuttle_pos_m: 15,     // Posição shuttle
        trimming_on: false,    // Trimming ativo
        dust_supp_on: true,    // Supressor de pó
        ship_name: 'MV GRAIN STAR',
        ship_dwt: 60000,       // DWT navio
        loaded_t: 0,           // Carregado
        target_t: 55000        // Meta carregamento
    },

    // ═══ TOTALIZADORES ═══
    totals: {
        loaded_t: 0,          // Total carregado
        received_t: 0,        // Total recebido
        daily_loaded_t: 0,
        daily_received_t: 0,
        energy_kwh: 0,
        runtime_h: 0
    },

    // ═══ ARMAZÉM ═══
    warehouse: {
        stock_t: 45000,       // Estoque atual
        capacity_t: 60000,    // Capacidade
        product: 'SOJA',
        moisture_pct: 13.5,
        temperature_c: 28
    },

    // ═══ COMUNICAÇÃO ═══
    comm: {
        messages_sent: 0,
        messages_ok: 0,
        messages_fail: 0
    },

    // ═══ ALARMES ═══
    alarms: [],

    lastUpdate: Date.now()
};

const now = Date.now();
const dt = Math.min((now - state.lastUpdate) / 1000, 2);
state.lastUpdate = now;
state.time_s += dt;
state.totals.runtime_h += dt / 3600;

// ═══════════════════════════════════════════════════════════════
// FUNÇÕES AUXILIARES
// ═══════════════════════════════════════════════════════════════

const firstOrderLag = (current, target, tau, dt) => {
    const alpha = dt / (tau + dt);
    return current + alpha * (target - current);
};

const noise = (base, variance) => 
    base * (1 + (Math.random() - 0.5) * 2 * variance);

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

const checkAlarm = (condition, id, message, severity) => {
    const exists = state.alarms.find(a => a.id === id);
    if (condition && !exists) {
        state.alarms.push({ id, message, severity, time: state.time_s });
    } else if (!condition && exists) {
        state.alarms = state.alarms.filter(a => a.id !== id);
    }
};

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DOS VAZADORES (ARZ_GATES)
// ═══════════════════════════════════════════════════════════════

let totalGateFlow = 0;
state.gates.forEach((gate, i) => {
    if (!gate.fault) {
        // Atuação hidráulica - resposta lenta
        gate.opening = firstOrderLag(gate.opening, gate.setpoint, gate.tau, dt);
    }

    // Vazão proporcional à abertura (não linear)
    const flowFactor = Math.pow(gate.opening / 100, 0.8);
    const targetFlow = flowFactor * gate.max_flow;
    gate.flow = noise(firstOrderLag(gate.flow, targetFlow, 1.5, dt), 0.03);
    gate.flow = Math.max(0, gate.flow);

    totalGateFlow += gate.flow;

    // Alarme de falha
    checkAlarm(gate.fault, `ARZ_GATE${gate.id}_FAULT`, `Vazador ${gate.id} em falha`, 'HIGH');
});

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DAS CORREIAS
// ═══════════════════════════════════════════════════════════════

function simulateBelt(belt, inputFlow, dt) {
    if (!belt.running || belt.pull_cord) {
        belt.speed_mps = firstOrderLag(belt.speed_mps, 0, 3.0, dt);
        belt.flow_tph = 0;
        belt.load_pct = 0;
        belt.power_kw = belt.speed_mps > 0.1 ? 5 : 0; // Potência residual
        belt.current_a = belt.power_kw * 1000 / (440 * 1.732 * 0.85);
        belt.motor_temp_c = firstOrderLag(belt.motor_temp_c, 25, 120, dt);
        return 0;
    }

    // Velocidade com rampa
    belt.speed_mps = firstOrderLag(belt.speed_mps, belt.speed_sp, 5.0, dt);

    // Vazão limitada pela capacidade
    belt.flow_tph = Math.min(inputFlow, belt.capacity_tph);
    belt.load_pct = (belt.flow_tph / belt.capacity_tph) * 100;

    // Potência: P = k1 + k2 * carga + k3 * velocidade
    const k1 = 8;   // Potência base
    const k2 = belt.capacity_tph / 1000 * 25;  // Fator de carga
    const k3 = 5;   // Fator de velocidade
    belt.power_kw = noise(k1 + (belt.load_pct/100) * k2 + belt.speed_mps * k3, 0.02);

    // Corrente do motor
    belt.current_a = belt.power_kw * 1000 / (440 * 1.732 * 0.85);

    // Temperatura do motor (sobe com carga)
    const tempTarget = 35 + (belt.load_pct / 100) * 25;
    belt.motor_temp_c = firstOrderLag(belt.motor_temp_c, tempTarget, 300, dt);
    belt.motor_temp_c = noise(belt.motor_temp_c, 0.01);

    // Temperatura do mancal
    belt.bearing_temp_c = belt.motor_temp_c + noise(5, 0.1);

    // Vibração (aumenta com carga e tempo)
    belt.vibration_mms = noise(0.8 + (belt.load_pct / 100) * 0.8, 0.15);

    // Detecção de patinamento
    belt.belt_slip = belt.load_pct > 95 && Math.random() < 0.001;

    // Alarmes
    const beltName = Object.keys(state.belts).find(k => state.belts[k] === belt);
    checkAlarm(belt.motor_temp_c > 65, `${beltName}_HIGH_TEMP`, `${beltName} temp motor alta: ${belt.motor_temp_c.toFixed(1)}°C`, 'MEDIUM');
    checkAlarm(belt.bearing_temp_c > 70, `${beltName}_BEARING_TEMP`, `${beltName} temp mancal alta: ${belt.bearing_temp_c.toFixed(1)}°C`, 'HIGH');
    checkAlarm(belt.vibration_mms > 4.0, `${beltName}_HIGH_VIB`, `${beltName} vibração alta: ${belt.vibration_mms.toFixed(1)} mm/s`, 'MEDIUM');
    checkAlarm(belt.belt_slip, `${beltName}_SLIP`, `${beltName} patinamento detectado`, 'HIGH');
    checkAlarm(belt.pull_cord, `${beltName}_PULLCORD`, `${beltName} cordinha de emergência acionada`, 'CRITICAL');

    return belt.flow_tph;
}

// CORR01: Recebe dos vazadores
const corr01Output = simulateBelt(state.belts.CORR01, totalGateFlow, dt);

// CORR02: Recebe da CORR01
const corr02Output = simulateBelt(state.belts.CORR02, corr01Output, dt);

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DO ELEVADOR (ELV01)
// ═══════════════════════════════════════════════════════════════

if (state.elevator.running) {
    state.elevator.speed_mps = firstOrderLag(state.elevator.speed_mps, state.elevator.speed_sp, 8.0, dt);
    state.elevator.flow_tph = Math.min(corr02Output, state.elevator.capacity_tph);

    // Potência do elevador (maior que correias devido à elevação)
    const liftHeight = 45; // metros
    const liftPower = (state.elevator.flow_tph / 3600) * 9.81 * liftHeight / 0.7; // kW
    state.elevator.power_kw = noise(20 + liftPower, 0.02);
    state.elevator.current_a = state.elevator.power_kw * 1000 / (440 * 1.732 * 0.85);

    // Temperaturas
    state.elevator.motor_temp_c = noise(firstOrderLag(state.elevator.motor_temp_c, 45 + (state.elevator.flow_tph/1500) * 20, 200, dt), 0.01);
    state.elevator.bearing_temp_c = state.elevator.motor_temp_c + noise(8, 0.1);

    // Vibração
    state.elevator.vibration_mms = noise(1.2 + (state.elevator.flow_tph/1500) * 0.8, 0.1);

    // Contagem de canecas
    state.elevator.bucket_count += Math.floor(state.elevator.flow_tph / 50 * dt);

    // Nível no pé do elevador
    state.elevator.boot_level_pct = clamp(30 + (corr02Output - state.elevator.flow_tph) * 0.1, 10, 90);

    // Pressão na cabeça
    state.elevator.head_pressure = noise((state.elevator.flow_tph / 1500) * 100, 0.05);
} else {
    state.elevator.speed_mps = firstOrderLag(state.elevator.speed_mps, 0, 10, dt);
    state.elevator.flow_tph = 0;
    state.elevator.power_kw = 0;
}

// Alarmes do elevador
checkAlarm(state.elevator.motor_temp_c > 70, 'ELV01_HIGH_TEMP', `Elevador temp alta: ${state.elevator.motor_temp_c.toFixed(1)}°C`, 'HIGH');
checkAlarm(state.elevator.boot_level_pct > 80, 'ELV01_BOOT_HIGH', `Elevador nível pé alto: ${state.elevator.boot_level_pct.toFixed(0)}%`, 'MEDIUM');
checkAlarm(state.elevator.vibration_mms > 4.5, 'ELV01_HIGH_VIB', `Elevador vibração alta: ${state.elevator.vibration_mms.toFixed(1)} mm/s`, 'HIGH');

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DA BALANÇA DE FLUXO (BLC01) - CRÍTICO!
// ═══════════════════════════════════════════════════════════════

const scaleInput = state.elevator.flow_tph;
state.scale.flow_tph = noise(scaleInput, state.scale.accuracy_pct / 100);
state.scale.belt_load_kg_m = state.scale.flow_tph / 3.6 / state.scale.speed_mps;

// Totalização
const massIncrement = (state.scale.flow_tph / 3600) * dt;
state.scale.total_t += massIncrement;
state.scale.daily_total_t += massIncrement;

// Alarmes da balança
checkAlarm(!state.scale.calibration_ok, 'BLC01_CAL_FAULT', 'Balança: calibração vencida', 'HIGH');
checkAlarm(!state.scale.zero_ok, 'BLC01_ZERO_FAULT', 'Balança: erro de zero', 'MEDIUM');
checkAlarm(Math.abs(state.scale.flow_tph - state.scale.flow_sp) > 200, 'BLC01_FLOW_DEV', `Balança: desvio de vazão ${(state.scale.flow_tph - state.scale.flow_sp).toFixed(0)} t/h`, 'LOW');

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DA CORREIA 03 (após balança)
// ═══════════════════════════════════════════════════════════════

const corr03Output = simulateBelt(state.belts.CORR03, state.scale.flow_tph, dt);

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DO TRIPPER CAR (TRP01)
// ═══════════════════════════════════════════════════════════════

const tripperError = state.tripper.target_position - state.tripper.position_m;
if (Math.abs(tripperError) > 0.5) {
    state.tripper.speed_mpm = clamp(tripperError * 2, -30, 30);
    state.tripper.position_m += (state.tripper.speed_mpm / 60) * dt;
} else {
    state.tripper.speed_mpm = 0;
}

state.tripper.limit_left = state.tripper.position_m < 5;
state.tripper.limit_right = state.tripper.position_m > 195;
state.tripper.position_m = clamp(state.tripper.position_m, 0, 200);

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DO SHIPLOADER (SLD01)
// ═══════════════════════════════════════════════════════════════

const sldInput = corr03Output;
state.shiploader.flow_tph = noise(firstOrderLag(state.shiploader.flow_tph, Math.min(sldInput, state.shiploader.flow_sp), 2.0, dt), 0.02);

// Potência do shiploader
state.shiploader.power_kw = noise(30 + (state.shiploader.flow_tph / 2000) * 120, 0.02);
state.shiploader.current_a = state.shiploader.power_kw * 1000 / (440 * 1.732 * 0.85);

// Movimento da lança (oscilação suave)
state.shiploader.boom_angle_deg = noise(12, 0.02);
state.shiploader.slewing_deg = noise(0, 0.01) + Math.sin(state.time_s / 60) * 5;
state.shiploader.shuttle_pos_m = clamp(15 + Math.sin(state.time_s / 30) * 5, 5, 25);

// Carregamento do navio
const loadedIncrement = (state.shiploader.flow_tph / 3600) * dt;
state.shiploader.loaded_t += loadedIncrement;
state.totals.loaded_t += loadedIncrement;
state.totals.daily_loaded_t += loadedIncrement;

// ═══════════════════════════════════════════════════════════════
// ATUALIZAÇÃO DO ARMAZÉM
// ═══════════════════════════════════════════════════════════════

state.warehouse.stock_t -= loadedIncrement;
if (state.warehouse.stock_t < 5000) {
    state.warehouse.stock_t = 45000; // Simula reposição
}

// ═══════════════════════════════════════════════════════════════
// TOTALIZAÇÃO DE ENERGIA
// ═══════════════════════════════════════════════════════════════

const totalPower = 
    state.belts.CORR01.power_kw + 
    state.belts.CORR02.power_kw + 
    state.belts.CORR03.power_kw + 
    state.elevator.power_kw + 
    state.shiploader.power_kw;

state.totals.energy_kwh += (totalPower / 3600) * dt;

// ═══════════════════════════════════════════════════════════════
// SALVAR ESTADO E GERAR TAGS
// ═══════════════════════════════════════════════════════════════

context.set('state', state);

const data = [];

// ═══ TAGS DO SISTEMA ═══
data.push({ tag_name: 'SYS_RUNNING_PV', value: state.running ? 1 : 0, unit: '', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_MODE_PV', value: state.operation_mode === 'LOADING' ? 1 : 0, unit: '', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_RUNTIME_H_PV', value: state.totals.runtime_h, unit: 'h', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_TOTAL_POWER_KW_PV', value: totalPower, unit: 'kW', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_TOTAL_ENERGY_KWH_PV', value: state.totals.energy_kwh, unit: 'kWh', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_ACTIVE_ALARMS_PV', value: state.alarms.length, unit: '', protocol: 'INTERNAL' });

// ═══ TAGS DOS VAZADORES (4 unidades - OPC-UA) ═══
state.gates.forEach((gate) => {
    const num = String(gate.id).padStart(2, '0');
    data.push({ tag_name: `ARZ_GATE${num}_OPENING_PV`, value: gate.opening, unit: '%', protocol: 'OPC-UA' });
    data.push({ tag_name: `ARZ_GATE${num}_SETPOINT_PV`, value: gate.setpoint, unit: '%', protocol: 'OPC-UA' });
    data.push({ tag_name: `ARZ_GATE${num}_FLOW_TPH_PV`, value: gate.flow, unit: 't/h', protocol: 'OPC-UA' });
    data.push({ tag_name: `ARZ_GATE${num}_FAULT_PV`, value: gate.fault ? 1 : 0, unit: '', protocol: 'OPC-UA' });
});

// ═══ TAGS DAS CORREIAS (MODBUS) ═══
Object.entries(state.belts).forEach(([name, belt]) => {
    data.push({ tag_name: `${name}_RUNNING_PV`, value: belt.running ? 1 : 0, unit: '', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_SPEED_MPS_PV`, value: belt.speed_mps, unit: 'm/s', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_FLOW_TPH_PV`, value: belt.flow_tph, unit: 't/h', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_LOAD_PCT_PV`, value: belt.load_pct, unit: '%', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_POWER_KW_PV`, value: belt.power_kw, unit: 'kW', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_CURRENT_A_PV`, value: belt.current_a, unit: 'A', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_MOTOR_TEMP_C_PV`, value: belt.motor_temp_c, unit: '°C', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_BEARING_TEMP_C_PV`, value: belt.bearing_temp_c, unit: '°C', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_VIBRATION_MMS_PV`, value: belt.vibration_mms, unit: 'mm/s', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_BELT_SLIP_PV`, value: belt.belt_slip ? 1 : 0, unit: '', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_PULLCORD_PV`, value: belt.pull_cord ? 1 : 0, unit: '', protocol: 'MODBUS' });
});

// ═══ TAGS DO ELEVADOR (PROFINET) ═══
data.push({ tag_name: 'ELV01_RUNNING_PV', value: state.elevator.running ? 1 : 0, unit: '', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_SPEED_MPS_PV', value: state.elevator.speed_mps, unit: 'm/s', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_FLOW_TPH_PV', value: state.elevator.flow_tph, unit: 't/h', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_POWER_KW_PV', value: state.elevator.power_kw, unit: 'kW', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_CURRENT_A_PV', value: state.elevator.current_a, unit: 'A', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_MOTOR_TEMP_C_PV', value: state.elevator.motor_temp_c, unit: '°C', protocol: 'PROFINET' });
