    fill: state.alarms.length > 0 ? 'yellow' : 'green',
    shape: 'dot',
    text: `${data.length} tags | ${state.scale.flow_tph.toFixed(0)} t/h | ${state.shiploader.loaded_t.toFixed(0)}/${state.shiploader.target_t} t`
});

msg.payload = {
    data: data.map(d => ({
        tag_name: d.tag_name,
        value: parseFloat(d.value.toFixed(2)),
        quality: 'Good',
        timestamp: timestamp,
        source: 'grain_terminal_simulator',
        unit: d.unit,
        metadata: { protocol: d.protocol }
    })),
    source_id: 'nodered-grain-terminal',
    source_type: 'plc_simulator'
};

return msg;

const state = global.get('grain_terminal_state');
if (state) {
    state.comm.messages_ok++;
    global.set('grain_terminal_state', state);
}
return null;

const state = global.get('grain_terminal_state');
if (state) {
    state.comm.messages_fail++;
    global.set('grain_terminal_state', state);
}
node.status({fill:'red', shape:'dot', text:`Error: ${msg.statusCode}`});
return msg;
